import { type PlaybackHint } from './playbackHints';
import { type PlaybackRestriction } from './playbackRestriction';
/** 只认 14 个字母或数字（前后空白去掉）；其他都当没给。 */
export declare const validMediaIdOf: (value: unknown) => string | undefined;
/**
 * `trackInfo` 是单曲详情（`track_info`），读不到时是 `undefined`；`callerMediaId` 是前端给的、已经验过的 media id。
 * 能要试听文件就回文件名要用的 media id（前端给的优先，否则详情里的 `file.media_mid`），不能就回 `undefined`。
 */
export declare const previewMediaIdOf: (trackInfo: unknown, callerMediaId?: string) => string | undefined;
/**
 * 详情宣告的试听长度（毫秒）：`file.e_30s − file.b_30s`。实测搜索结果 39 首，有试听的都是 60 秒、两者相减都是 60000，
 * `b_30s` 不少不是 0，所以不能直接用 `e_30s`。`e_30s` 不是正整数就当没有，不拿 30 秒顶上；
 * 详情没有 `b_30s` 时和以前一样用 `e_30s`；`b_30s` 给了却读不懂、是负数或不在 `e_30s` 之前，当没有。
 * `b_30s` 是官方网页试听文件的起点，不是这里要的 RS02 文件的起点（实测对不上），所以只拿来算长度，不交位置。
 */
export declare const previewDurationMsOf: (trackInfo: unknown) => number | undefined;
/** 详情里 `size_try` 正好是 0（整数或纯数字字符串）才算确定没有试听文件；缺字段、负数、读不到都不算。 */
export declare const previewFileMissingOf: (trackInfo: unknown) => boolean;
/** 不要试听文件的那首歌：和拿不到链接一样是 `url_unavailable`，提示是「试听不可用」。 */
export declare const previewUnavailableRestriction: (authenticated: boolean, missing?: boolean) => PlaybackRestriction & {
    hint: PlaybackHint;
};
